namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required")]
    [MinLength(10, ErrorMessage = "Please provide more detail for ingredients")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required")]
    [MinLength(10, ErrorMessage = "Please provide more detail for the steps")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil.",
            AverageRating = 4.5, RatingCount = 24
        },
        new Recipe
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCoriander\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 minutes.\n5. Add cream and cooked chicken.\n6. Simmer 10 more minutes. Serve with rice.",
            AverageRating = 4.8, RatingCount = 42
        },
        new Recipe
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream.",
            AverageRating = 4.2, RatingCount = 18
        },
        new Recipe
        {
            Id = 4, Title = "Pad Thai", Category = "Asian",
            Ingredients = "Rice noodles\nShrimp or tofu\nEgg\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
            Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Make sauce: mix tamarind, fish sauce, and sugar.\n3. Stir-fry shrimp/tofu, set aside.\n4. Scramble egg in wok.\n5. Add noodles and sauce, toss until coated.\n6. Add protein, bean sprouts, and green onions.\n7. Serve with peanuts and lime wedge.",
            AverageRating = 4.6, RatingCount = 31
        },
        new Recipe
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract\nPowdered sugar",
            Steps = "1. Preheat oven to 425°F (220°C). Butter ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs.\n5. Add flour and vanilla, fold gently.\n6. Pour into ramekins, bake 12-14 minutes.\n7. Invert onto plates, serve immediately.",
            AverageRating = 4.9, RatingCount = 56
        },
        new Recipe
        {
            Id = 6, Title = "Caesar Salad", Category = "Salads",
            Ingredients = "Romaine lettuce\nParmesan cheese\nCroutons\nCaesar dressing\nLemon juice\nGarlic\nAnchovy paste\nOlive oil",
            Steps = "1. Wash and chop romaine lettuce.\n2. Make dressing: blend garlic, anchovy, lemon, olive oil, and parmesan.\n3. Toss lettuce with dressing.\n4. Top with croutons and shaved parmesan.\n5. Serve immediately.",
            AverageRating = 4.0, RatingCount = 15
        }
    };

    private readonly List<RecipeCategory> _categories = new()
    {
        new RecipeCategory { Name = "Italian", Description = "Classic pasta, pizza, and Mediterranean flavors", Icon = "🍝" },
        new RecipeCategory { Name = "Indian", Description = "Rich curries, aromatic spices, and tandoori dishes", Icon = "🍛" },
        new RecipeCategory { Name = "Mexican", Description = "Tacos, burritos, and vibrant salsas", Icon = "🌮" },
        new RecipeCategory { Name = "Asian", Description = "Stir-fries, noodles, and umami-rich dishes", Icon = "🍜" },
        new RecipeCategory { Name = "Desserts", Description = "Sweet treats, cakes, and indulgent delights", Icon = "🍰" },
        new RecipeCategory { Name = "Salads", Description = "Fresh, healthy, and colorful bowls", Icon = "🥗" }
    };

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Max(r => r.Id) + 1,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int rating)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalRating = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalRating + rating) / recipe.RatingCount, 1);
    }
}

